-- Additive access foundation. No identity or provider access is assigned by this migration.
CREATE TABLE permission_definitions (
 permission_key VARCHAR(100) PRIMARY KEY, display_name VARCHAR(160) NOT NULL, description VARCHAR(500) NOT NULL,
 family VARCHAR(60) NOT NULL, risk VARCHAR(10) NOT NULL CHECK (risk IN ('LOW','MEDIUM','HIGH','CRITICAL')),
 allowed_scopes VARCHAR(500) NOT NULL, actor_types VARCHAR(500) NOT NULL, channels VARCHAR(300) NOT NULL,
 sensitive_data VARCHAR(30) NOT NULL, dependencies VARCHAR(1000) NOT NULL, conflicts VARCHAR(1000) NOT NULL,
 active BOOLEAN NOT NULL, executable BOOLEAN NOT NULL, workflow_gated BOOLEAN NOT NULL, recent_auth BOOLEAN NOT NULL
);
CREATE TABLE role_templates (
 id UUID PRIMARY KEY, template_key VARCHAR(100) NOT NULL UNIQUE, display_name VARCHAR(160) NOT NULL,
 description VARCHAR(500) NOT NULL, purpose VARCHAR(500) NOT NULL, family VARCHAR(60) NOT NULL,
 system_template BOOLEAN NOT NULL, organization_id UUID NOT NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE','RETIRED')),
 revision BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL
);
CREATE TABLE role_template_versions (
 id UUID PRIMARY KEY, template_id UUID NOT NULL REFERENCES role_templates(id), version_number INTEGER NOT NULL,
 status VARCHAR(20) NOT NULL CHECK (status IN ('DRAFT','VALIDATED','PUBLISHED','RETIRED')), revision BIGINT NOT NULL DEFAULT 0,
 actor_type VARCHAR(40) NOT NULL, channel VARCHAR(40) NOT NULL, effective_from TIMESTAMP WITH TIME ZONE,
 retired_at TIMESTAMP WITH TIME ZONE, created_by VARCHAR(255) NOT NULL, published_by VARCHAR(255),
 created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(template_id,version_number)
);
CREATE TABLE role_permission_grants (
 version_id UUID NOT NULL REFERENCES role_template_versions(id), permission_key VARCHAR(100) NOT NULL REFERENCES permission_definitions(permission_key),
 scope_type VARCHAR(40) NOT NULL CHECK (scope_type IN ('SELF','ASSIGNED_CASES','MANAGED_CLINICIANS','ORGANIZATION','ASSIGNED_ORGANIZATIONS','SPECIFIC_RESOURCE','PLATFORM')),
 relationship_type VARCHAR(40), PRIMARY KEY(version_id,permission_key,scope_type)
);
-- A stable per-subject parent lock serializes grants/revocations and cross-role SoD checks.
CREATE TABLE access_subjects (
 subject VARCHAR(255) PRIMARY KEY, active BOOLEAN NOT NULL, revision BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE access_memberships (
 subject VARCHAR(255) NOT NULL REFERENCES access_subjects(subject), organization_id UUID NOT NULL,
 status VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE','PENDING','REVOKED')),
 effective_from TIMESTAMP WITH TIME ZONE NOT NULL, effective_to TIMESTAMP WITH TIME ZONE,
 revision BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(255) NOT NULL, reason VARCHAR(1000) NOT NULL,
 PRIMARY KEY(subject,organization_id), CHECK(effective_to IS NULL OR effective_to > effective_from)
);
CREATE TABLE role_assignments (
 id UUID PRIMARY KEY, subject VARCHAR(255) NOT NULL, version_id UUID NOT NULL REFERENCES role_template_versions(id),
 organization_id UUID NOT NULL, scope_type VARCHAR(40) NOT NULL CHECK (scope_type IN ('SELF','ASSIGNED_CASES','MANAGED_CLINICIANS','ORGANIZATION','ASSIGNED_ORGANIZATIONS','SPECIFIC_RESOURCE','PLATFORM')),
 target_type VARCHAR(60), target_id VARCHAR(255), effective_from TIMESTAMP WITH TIME ZONE NOT NULL,
 effective_to TIMESTAMP WITH TIME ZONE, status VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE','PENDING','REVOKED')),
 source VARCHAR(40) NOT NULL, assigned_by VARCHAR(255) NOT NULL, reason VARCHAR(1000) NOT NULL,
 revoked_at TIMESTAMP WITH TIME ZONE, revision BIGINT NOT NULL DEFAULT 0,
 FOREIGN KEY(subject,organization_id) REFERENCES access_memberships(subject,organization_id),
 CHECK(effective_to IS NULL OR effective_to > effective_from),
 CHECK(scope_type <> 'SPECIFIC_RESOURCE' OR (target_type IS NOT NULL AND target_id IS NOT NULL)),
 CHECK(scope_type <> 'PLATFORM' OR organization_id = '00000000-0000-0000-0000-000000000001')
);
CREATE INDEX idx_access_assignments_subject_org ON role_assignments(subject,organization_id,status);
CREATE TABLE resource_relationships (
 id UUID PRIMARY KEY, subject VARCHAR(255) NOT NULL, organization_id UUID NOT NULL,
 relationship_type VARCHAR(40) NOT NULL CHECK (relationship_type IN ('MANAGES','ASSISTS','SUPERVISES','COORDINATES','ASSIGNED_TO','REPRESENTS','VERIFIES','PREFERRED_COORDINATOR','PREFERRED_COORDINATOR_TEAM')),
 target_type VARCHAR(60) NOT NULL, target_id VARCHAR(255) NOT NULL,
 effective_from TIMESTAMP WITH TIME ZONE NOT NULL, effective_to TIMESTAMP WITH TIME ZONE,
 status VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE','PENDING','REVOKED')), created_by VARCHAR(255) NOT NULL,
 reason VARCHAR(1000) NOT NULL, revision BIGINT NOT NULL DEFAULT 0, revoked_at TIMESTAMP WITH TIME ZONE,
 FOREIGN KEY(subject,organization_id) REFERENCES access_memberships(subject,organization_id),
 CHECK(effective_to IS NULL OR effective_to > effective_from)
);
CREATE INDEX idx_access_relationship_scope ON resource_relationships(subject,organization_id,relationship_type,target_id);
CREATE TABLE access_bootstrap (
 id INTEGER PRIMARY KEY CHECK (id = 1), completed_at TIMESTAMP WITH TIME ZONE, subject VARCHAR(255)
);
